package com.printflow.customer;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.time.LocalDate;import org.apache.pdfbox.Loader;import org.apache.pdfbox.text.PDFTextStripper;import org.apache.pdfbox.rendering.PDFRenderer;import tools.jackson.databind.json.JsonMapper;
class InvoicePdfTest {
 @Test void invoiceHasImmutableAgreementAmountsTermsAndReadablePagination()throws Exception{
  var json=JsonMapper.builder().build();var snapshot=new LinkedHashMap<String,Object>();snapshot.put("customer","Synthetic customer");snapshot.put("email","synthetic@example.test");snapshot.put("version",2);snapshot.put("id",UUID.randomUUID());snapshot.put("scope","250 wedding invitations with envelopes");snapshot.put("total_paise",125000);snapshot.put("terms","Agreed print terms. ".repeat(160));snapshot.put("line_items",json.writeValueAsString(List.of(Map.of("description","Wedding invitations","quantity",250,"unitPaise",500,"taxBps",0,"totalPaise",125000))));snapshot.put("policy",Map.of("advance_paise",62500,"reason","Half advance and balance before dispatch"));byte[] bytes=new InvoicePdf(json).create(7,LocalDate.of(2026,10,24),snapshot);
  try(var doc=Loader.loadPDF(bytes)){String text=new PDFTextStripper().getText(doc);assertTrue(text.contains("INV-7"));assertTrue(text.contains("INR 1250.00"));assertTrue(text.contains("INR 625.00"));assertTrue(text.contains("not a GST tax invoice"));assertTrue(text.contains("Synthetic customer"));assertTrue(doc.getNumberOfPages()>1);assertTrue(text.contains("Page 1 /"));var image=new PDFRenderer(doc).renderImageWithDPI(0,110);var target=java.nio.file.Path.of("build/invoice-preview.png");java.nio.file.Files.createDirectories(target.getParent());javax.imageio.ImageIO.write(image,"PNG",target.toFile());}
 }
 @Test void signaturesRejectModifiedOrMalformedPayloads()throws Exception{String secret="synthetic-secret",message="order_test|pay_test";var mac=javax.crypto.Mac.getInstance("HmacSHA256");mac.init(new javax.crypto.spec.SecretKeySpec(secret.getBytes(java.nio.charset.StandardCharsets.UTF_8),"HmacSHA256"));String signature=HexFormat.of().formatHex(mac.doFinal(message.getBytes(java.nio.charset.StandardCharsets.UTF_8)));assertTrue(RazorpayClient.signature(secret,message.getBytes(),signature));assertFalse(RazorpayClient.signature(secret,(message+"x").getBytes(),signature));assertFalse(RazorpayClient.signature(secret,message.getBytes(),"bad"));assertFalse(RazorpayClient.signature(secret,message.getBytes(),null));}
}
